class NotesViewModel(private val saved: SavedStateHandle) : ViewModel() {
    val draft = saved.getStateFlow("draft", "")
    private val _notes = MutableStateFlow<List<String>>(emptyList())
    val notes = _notes.asStateFlow()

    fun onDraftChange(text: String) { saved["draft"] = text }
    fun save() {
        val text = draft.value.trim()
        if (text.isEmpty()) return
        _notes.value = listOf(text) + _notes.value
        saved["draft"] = ""
    }
}
